const listShipments = `-- name: ListShipments :many
SELECT s.id, s.tenant_id, s.sales_order_id, s.customer_id, s.shipment_no, s.status, s.location_id, s.ship_date, s.carrier, s.tracking_ref, s.bol_reference, s.notes, s.shipped_at, s.shipped_by, s.cancelled_at, s.cancel_reason, s.created_by, s.created_at, s.updated_at, c.name AS customer_name,
       COALESCE(so.order_no, 0)::INTEGER AS order_no,
       COUNT(sl.id)::INTEGER AS line_count,
       COALESCE(SUM(sl.bottles), 0)::INTEGER AS bottles
FROM shipments s
JOIN customers c ON c.id = s.customer_id
LEFT JOIN sales_orders so ON so.id = s.sales_order_id
LEFT JOIN shipment_lines sl ON sl.shipment_id = s.id
WHERE ($1::BOOLEAN = FALSE OR s.status = 'picking')
GROUP BY s.id, c.name, so.order_no
ORDER BY s.ship_date NULLS LAST, s.shipment_no DESC
`

