const reservedBottlesForProduct = `-- name: ReservedBottlesForProduct :one
SELECT COALESCE(SUM(l.bottles_ordered - l.bottles_shipped), 0)::INTEGER AS reserved
FROM sales_order_lines l
JOIN sales_orders so ON so.id = l.sales_order_id
WHERE l.product_id = $1
  AND so.status IN ('confirmed', 'partially_shipped')
  AND l.bottles_shipped < l.bottles_ordered
`

// What is spoken for on confirmed, unshipped order lines. Deliberately a
// read rather than a decrement: the alcohol has not moved, and a B266
// built on promises rather than movements would be wrong. This tells the
// screen; it does not tell the ledger.
func (q *Queries) ReservedBottlesForProduct(ctx context.Context, productID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, reservedBottlesForProduct, productID)
	var reserved int32
	err := row.Scan(&reserved)
	return reserved, err
}

const salesOrderOutstanding = `-- name: SalesOrderOutstanding :one
SELECT
    COUNT(*) FILTER (WHERE l.bottles_shipped < l.bottles_ordered)::INTEGER AS lines_outstanding,
    COUNT(*) FILTER (WHERE l.bottles_shipped > 0)::INTEGER                 AS lines_started
FROM sales_order_lines l
WHERE l.sales_order_id = $1
`

type SalesOrderOutstandingRow struct {
	LinesOutstanding int32 `json:"lines_outstanding"`
	LinesStarted     int32 `json:"lines_started"`
}

func (q *Queries) SalesOrderOutstanding(ctx context.Context, salesOrderID uuid.UUID) (SalesOrderOutstandingRow, error) {
	row := q.db.QueryRow(ctx, salesOrderOutstanding, salesOrderID)
	var i SalesOrderOutstandingRow
	err := row.Scan(&i.LinesOutstanding, &i.LinesStarted)
	return i, err
}

