const setSalesOrderStatus = `-- name: SetSalesOrderStatus :one
UPDATE sales_orders SET
    status       = $1::sales_order_status,
    confirmed_at = CASE WHEN $1::sales_order_status = 'confirmed'
                         AND confirmed_at IS NULL THEN NOW() ELSE confirmed_at END,
    confirmed_by = CASE WHEN $1::sales_order_status = 'confirmed'
                         AND confirmed_by IS NULL THEN $2::UUID ELSE confirmed_by END,
    cancelled_at = CASE WHEN $1::sales_order_status = 'cancelled'
                        THEN NOW() ELSE cancelled_at END,
    cancel_reason = CASE WHEN $1::sales_order_status = 'cancelled'
                         THEN $3::TEXT ELSE cancel_reason END
WHERE id = $4
RETURNING id, tenant_id, customer_id, order_no, status, ordered_on, required_by, customer_reference, price_list_id, location_id, notes, confirmed_at, confirmed_by, cancelled_at, cancel_reason, created_by, created_at, updated_at
`

